#if UNITY_EDITOR
using System.Collections.Generic;using HabitatShift.Core;using UnityEngine;
namespace HabitatShift.LevelLabR10 { public sealed class R10Playtest { public ContinuousSession Session{get;private set;} public readonly List<TraceGestureV1> gestures=new List<TraceGestureV1>();readonly LevelDto level;readonly RulesetDto rules;readonly string fingerprint;string active;Vector2 press;readonly List<FloatPair> path=new List<FloatPair>();public R10Playtest(LevelDto l,RulesetDto r,string fp){level=R10Storage.Clone(l);rules=r;fingerprint=fp;Session=new ContinuousSession(level,rules);}public bool Begin(string id,Vector2 p){if(!Session.BeginDrag(id,p))return false;active=id;press=p;path.Clear();return true;}public void Move(Vector2 p){if(active==null)return;Session.MovePointer(p);path.Add(new FloatPair{x=p.x,y=p.y});}public bool End(){if(active==null)return false;var committed=Session.EndDrag(false);if(committed&&path.Count>0)gestures.Add(new TraceGestureV1{habitatId=active,press=new FloatPair{x=press.x,y=press.y},boardPath=path.ToArray(),checkpoint=SolutionTraceRunner.Fingerprint(Session.Committed)});active=null;path.Clear();return committed;}public void Undo(){if(Session.Undo()&&gestures.Count>0)gestures.RemoveAt(gestures.Count-1);}public void Restart(){Session.Restart();gestures.Clear();active=null;path.Clear();}public SolutionTraceV1 Trace(){return new SolutionTraceV1{levelId=level.id,catalogFingerprint=fingerprint,gestures=gestures.ToArray()};}}}
#endif